get_dashboard_kpi_options.code:
const response = await client.dashboardKpis.getDashboardKpiOptions();
console.log(response.map.min, response.map.max, response.map.selected);
for (const group of response.map.groups) {
    for (const metric of group.metrics) {
        console.log(group.key, metric.key, metric.label, metric.in_use);
    }
}

get_dashboard_kpi_selection.code:
const response = await client.dashboardKpis.getDashboardKpiSelection({duration: 'last_7_days'});
for (const kpi of response.map.selected) {
    console.log(kpi.position, kpi.key, kpi.value, kpi.previous_value, kpi.change_percent);
}

update_dashboard_kpi_selection.code:
const response = await client.dashboardKpis.updateDashboardKpiSelection(
    {metrics: ['total_sales', 'total_orders', 'aov']},
    {duration: 'last_7_days'},
);
for (const kpi of response.map.selected) {
    console.log(kpi.position, kpi.key, kpi.value);
}
